SELECT
    id,
    job_requirements
FROM t_job_detail

    is_deleted = 0

        AND city_name = #{cityName}


        AND position_name = #{positionName}


        AND id > #{startIndex}


ORDER BY id ASC
LIMIT #{limit}

SELECT id, position_name, html_url as url, city_name, job_requirements, employee_benefits, detail_data FROM t_job_detail
is_deleted = 0
AND city_name = #{cityName}
AND position_name = #{positionName}
AND id > #{startIndex}
ORDER BY id ASC LIMIT #{limit}
